INSERT INTO `onl_cgform_enhance_js` VALUES ('0b326acbbc8e52c9c9ecdb19342fc3cf','show(){\n   console.log(\'form\',that)\n   //this.form.setFieldsValue({\"name\":\"name值\"})  \n  that.$nextTick(() => {\n           //age是对应表的字段名\n            that.form.setFieldsValue({\"age\":\"999\"})\n          });\n}\n\nonlChange(){\n   return {\n     \n     sex(){\n        let value = event.value\n        //alert(\'触发控件\',value)\n        \n         //性别改动，年龄归零\n        if(value!=null && value!=\"\"){   \n          let values = {\'age\':0}\n          that.triggleChangeValues(values)\n        }\n      }\n     \n    }\n }\n','form',NULL,'05a3a30dada7411c9109306aa4117068'),('274b5d741a0262d3411958f0c465c5f0','genereate_person_config(row){\nconsole.log(\'选择\',row)\nalert(row.name + \'，个人积分配置生成成功！\');\n}','list',NULL,'e2faf977fdaf4b25a524f58c2441a51c'),('2cbaf25f1edb620bea2d8de07f8233a1','air_china_post_materiel_item_onlChange(){\n    return {\n        wl_name(){\n           \n            let id = event.row.id\n            let cnum = event.row.num\n            let value = event.value\n            let targrt = event.target\n            let columnKey = event.column.key\n           let nval = 200*cnum\n           console.log(\'row\',event.row);\n           console.log(\'cnum\',cnum);\n           let otherValues = {\'jifen\': nval}\n              \n                that.triggleChangeValues(targrt,id,otherValues)\n\n        }\n    }\n}','form',NULL,'e67d26b610dd414c884c4dbb24e71ce3'),('32e7b7373abe0fb9c4dd608b4517f814','','form',NULL,'53a3e82b54b946c2b904f605875a275c'),('35d4ef464e5e8c87c9aa82ea89215fc1','','list',NULL,'e67d26b610dd414c884c4dbb24e71ce3'),('44cad4eec436328ed3cc134855f8d1d5',' onlChange(){\n   return {\n    name(that, event) {\n      that.executeMainFillRule()\n    }\n  }\n }','form',NULL,'4adec929a6594108bef5b35ee9966e9f'),('4569bc0e6126d2b8a0e0c69b9a47e8db','','list',NULL,'56efb74326e74064b60933f6f8af30ea'),('6dd82d8eac166627302230a809233481','ces_order_goods_onlChange(){\n    return {\n        num(){\n           \n            let id = event.row.id\n            let num = event.row.num\n            let price = event.row.price\n\n            let targrt = event.target\n            \n            let nval = price*num\n            console.log(\'row\',event.row);\n            console.log(\'num\',num);\n            console.log(\'that\',that);\n            let otherValues = {\'zong_price\': nval}\n              \n            that.triggleChangeValues(otherValues,id,targrt)\n   \n\n        }\n    }\n}','form',NULL,'56efb74326e74064b60933f6f8af30ea'),('85e7acd772c8ec322b97a1fd548007e0','','form',NULL,'09fd28e4b7184c1a9668496a5c496450'),('8b76f282ddc81ce99a129e90fdd977ce','','form',NULL,'86bf17839a904636b7ed96201b2fa6ea'),('90394fbc3d48978cc0937bc56f2d5370','','list',NULL,'deea5a8ec619460c9245ba85dbc59e80'),('ae9cf52fbe13cc718de2de6e1b3d6792','','list',NULL,'18f064d1ef424c93ba7a16148851664f'),('beec235f0b2d633ff3a6c395affdf59d','','list',NULL,'4adec929a6594108bef5b35ee9966e9f'),('c5ac9a2b2fd92ef68274f630b8aec78a','tjbpm(row){\n  alert(\'提交流程\')\n  console.log(\'row\',row)\n}\n\nbt1(){\n   console.log(\'that.table.selectionRows\',that.table.selectionRows)\n   console.log(\'that.table.selectedRowKeys\',that.table.selectedRowKeys)\n   console.log(\'that.table.dataSource\',that.table.dataSource)\n   alert(\'激活全部数据\')\n}','list',NULL,'05a3a30dada7411c9109306aa4117068'),('d7ddb7aa407f6deed75aac11f0a25f0e','222','list',NULL,'09fd28e4b7184c1a9668496a5c496450'),('f6f8f230566d09d4b66338955ffb5691','','form',NULL,'18f064d1ef424c93ba7a16148851664f'),('fd711738f58d5481ca0ce9bc3a415223','','list',NULL,'86bf17839a904636b7ed96201b2fa6ea');
